struct ProposedDimensions {
    let width: Double?
    let height: Double?

    func isUnconstrained() -> Bool {
        width == nil && height == nil
    }
}

let prop = ProposedDimensions(width: nil, height: nil)
print("Unconstrained: \(prop.isUnconstrained())")

struct LayoutItem {
    let width: Double
}

struct RowMeasure {
    var items: [LayoutItem] = []

    func totalWidth(spacing: Double) -> Double {
        let sum = items.reduce(0.0) { $0 + $1.width }
        let gaps = max(0, items.count - 1)
        return sum + Double(gaps) * spacing
    }
}

let row = RowMeasure(items: [LayoutItem(width: 40.0), LayoutItem(width: 60.0)])
print("Total: \(row.totalWidth(spacing: 10.0))")

struct LayoutBounds {
