struct CacheData {
    var lineBreaks: [Int] = []

    mutating func addBreak(at index: Int) {
        lineBreaks.append(index)
    }
}

var cache = CacheData()
cache.addBreak(at: 3)
cache.addBreak(at: 7)
print("Lines: \(cache.lineBreaks.count)")

struct CustomPriorityTrait {
    let priority: Int

    func isHigh() -> Bool {
        priority >= 10
    }
}

let trait = CustomPriorityTrait(priority: 15)
print("High: \(trait.isHigh())")

struct EqualWidthMeasurer {
    var widths: [Double] = [40.0, 85.0, 60.0]

    func maximumWidth() -> Double {
        widths.max() ?? 0.0
    }
}

let measurer = EqualWidthMeasurer()
print("Max: \(measurer.maximumWidth())")

struct CircularLayoutAngle {
    let index: Int
    let count: Int

    func angleDegrees() -> Double {
        Double(index) * (360.0 / Double(count))
    }
}

let c = CircularLayoutAngle(index: 2, count: 4)
print("Angle: \(c.angleDegrees())")

struct FlowRowCounter {
    var rows: [[String]] = []

    mutating func addRow(_ items: [String]) {
        rows.append(items)
    }
}

var counter = FlowRowCounter()
counter.addRow(["Tag1", "Tag2"])
counter.addRow(["Tag3"])
print("Rows: \(counter.rows.count)")

