struct SubviewsPlacer {
    var spacing: Double = 8.0

    func computeX(index: Int, itemWidth: Double) -> Double {
        Double(index) * (itemWidth + spacing)
    }
}

func testPlacer() {
    let placer = SubviewsPlacer()
    print("Position: \(placer.computeX(index: 2, itemWidth: 50.0))")
}

